package report_test

import (
	"errors"
	"io"
	"io/fs"
	"testing"
	"time"

	"github.com/damione1/Homeward/compat/ha/nha047"
	"github.com/damione1/Homeward/compat/ha/report"
)

// The virtual stream never stores its advertised contents. Both cases use at
// most MaxSourceBytes+2 generated bytes and count exactly what the reader asks.
type countedReportFS struct {
	declared  int64
	stream    int
	opens     int
	stats     int
	reads     int
	bytesRead int
	closes    int
}

func (source *countedReportFS) Open(name string) (fs.File, error) {
	source.opens++
	return &countedReportFile{source: source, name: name, remaining: source.stream}, nil
}

type countedReportFile struct {
	source    *countedReportFS
	name      string
	remaining int
}

func (file *countedReportFile) Stat() (fs.FileInfo, error) {
	file.source.stats++
	return countedReportInfo{name: file.name, size: file.source.declared}, nil
}

func (file *countedReportFile) Read(destination []byte) (int, error) {
	file.source.reads++
	if file.remaining == 0 {
		return 0, io.EOF
	}
	n := min(len(destination), file.remaining)
	for i := 0; i < n; i++ {
		destination[i] = 'x'
	}
	file.remaining -= n
	file.source.bytesRead += n
	return n, nil
}

func (file *countedReportFile) Close() error { file.source.closes++; return nil }

type countedReportInfo struct {
	name string
	size int64
}

func (info countedReportInfo) Name() string  { return info.name }
func (info countedReportInfo) Size() int64   { return info.size }
func (countedReportInfo) Mode() fs.FileMode  { return 0 }
func (countedReportInfo) ModTime() time.Time { return time.Time{} }
func (countedReportInfo) IsDir() bool        { return false }
func (countedReportInfo) Sys() any           { return nil }

func TestNHA047SourceBudgetRejectsDeclaredOversizeBeforeRead(t *testing.T) {
	empty, err := nha047.NewEvidence(nil)
	if err != nil {
		t.Fatal(err)
	}
	input := fanInput(t, empty)
	source := &countedReportFS{declared: report.MaxSourceBytes + 1, stream: 1}
	input.Sources = source
	_, err = report.Build(input)
	if !errors.Is(err, report.ErrLimit) {
		t.Errorf("want ErrLimit from metadata before materialization, got %v", err)
	}
	if source.opens != 1 || source.stats != 1 || source.reads != 0 || source.bytesRead != 0 || source.closes != 1 {
		t.Errorf("oversized source was read before admission: opens=%d stats=%d reads=%d bytes=%d closes=%d", source.opens, source.stats, source.reads, source.bytesRead, source.closes)
	}
}

func TestNHA047SourceBudgetCapsAStreamWhoseSizeIsUnreliable(t *testing.T) {
	empty, err := nha047.NewEvidence(nil)
	if err != nil {
		t.Fatal(err)
	}
	input := fanInput(t, empty)
	// Size reports zero, while the stream contains one more byte than the
	// allowed limit-detection sentinel. There is no backing large allocation.
	source := &countedReportFS{declared: 0, stream: report.MaxSourceBytes + 2}
	input.Sources = source
	_, err = report.Build(input)
	if !errors.Is(err, report.ErrLimit) {
		t.Errorf("want ErrLimit from the bounded stream, got %v", err)
	}
	if source.opens != 1 || source.closes != 1 || source.bytesRead > report.MaxSourceBytes+1 {
		t.Errorf("unbounded source read: opens=%d bytes=%d closes=%d", source.opens, source.bytesRead, source.closes)
	}
}
